<script setup>
import { onMounted,reactive,ref } from 'vue';import { ElMessage } from 'element-plus';import { createAdmin,listAdmin,updateAdmin } from '../../api/admin';import { options,text } from '../../utils/enums';import PageHeader from '../../components/PageHeader.vue';import AppPagination from '../../components/AppPagination.vue';import { messageOf } from '../../utils/request'
const state=reactive({list:[],total:0,pageNum:1,pageSize:10,keyword:'',role:'',loading:false});const open=ref(false);const form=reactive({id:null,username:'',password:'',realName:'',role:'CLIENT',phone:'',email:'',status:1});const load=async()=>{state.loading=true;try{const r=await listAdmin('users',{pageNum:state.pageNum,pageSize:state.pageSize,keyword:state.keyword||undefined,role:state.role||undefined});state.list=r.data.list;state.total=r.data.total}finally{state.loading=false}};const edit=(row={})=>{Object.assign(form,{id:null,username:'',password:'',realName:'',role:'CLIENT',phone:'',email:'',status:1,...row});open.value=true};const save=async()=>{try{const data={realName:form.realName,phone:form.phone,email:form.email,status:form.status};if(!form.id)Object.assign(data,{username:form.username,password:form.password,role:form.role});form.id?await updateAdmin('users',form.id,data):await createAdmin('users',data);ElMessage.success('用户已保存');open.value=false;load()}catch(e){ElMessage.error(messageOf(e))}};onMounted(load)
</script>
<template><div class="page"><PageHeader title="用户管理" description="查看并维护客户、代理人和管理员账号"><el-button type="primary" @click="edit()">新增用户</el-button></PageHeader><div class="toolbar"><div class="filters"><el-input v-model="state.keyword" placeholder="用户名" clearable/><el-select v-model="state.role" placeholder="角色" clearable><el-option v-for="o in options('role')" :key="o.value" v-bind="o"/></el-select><el-button @click="load">查询</el-button></div></div><div class="table-wrap"><el-table v-loading="state.loading" :data="state.list"><el-table-column prop="username" label="用户名"/><el-table-column prop="realName" label="姓名"/><el-table-column label="角色"><template #default="{row}">{{text('role',row.role)}}</template></el-table-column><el-table-column prop="phone" label="电话"/><el-table-column prop="email" label="邮箱" min-width="180"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.status?'success':'info'">{{text('userStatus',row.status)}}</el-tag></template></el-table-column><el-table-column width="80"><template #default="{row}"><el-button link @click="edit(row)">编辑</el-button></template></el-table-column></el-table></div><AppPagination v-model:page="state.pageNum" v-model:size="state.pageSize" :total="state.total" @change="load"/><el-dialog v-model="open" :title="form.id?'编辑用户':'新增用户'" width="min(580px,94vw)"><el-form class="form-grid" label-position="top"><el-form-item label="用户名"><el-input v-model="form.username" :disabled="!!form.id"/></el-form-item><el-form-item v-if="!form.id" label="初始密码"><el-input v-model="form.password" type="password" show-password/></el-form-item><el-form-item label="姓名"><el-input v-model="form.realName"/></el-form-item><el-form-item label="角色"><el-select v-model="form.role" :disabled="!!form.id"><el-option v-for="o in options('role')" :key="o.value" v-bind="o"/></el-select></el-form-item><el-form-item label="电话"><el-input v-model="form.phone"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item></el-form><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
